# 과목별로 점수를 모아 최고점과 응시 횟수를 알려줘요.
n = int(input())
records = {}
for _ in range(n):
    subject, score = input().split()
    # setdefault는 처음 나온 과목이면 빈 리스트를 만들어 줘요.
    records.setdefault(subject, []).append(int(score))

for subject in sorted(records):
    scores = records[subject]
    print(f"{subject}: 최고 {max(scores)}점, {len(scores)}번 응시")
